/*
 * wmi-unsecapp-ps.c -- hand-written glue for the Unsecured Apartment
 * proxy/stub DLL.
 *
 * The marshalling code itself is generated by widl from
 * wmi_unsecapp_ps.idl (see build.sh); this file only supplies the two
 * things MIDL would normally get from a hand-maintained .c file:
 *
 *   1. the CLSID this proxy/stub DLL is registered under, and
 *   2. the DllGetClassObject / DllCanUnloadNow / DllRegisterServer /
 *      DllUnregisterServer entry points, which rpcproxy.h builds from the
 *      generated proxy file list via DLLDATA_ROUTINES().
 *
 * Wiring, once installed:
 *
 *   HKCR\Interface\{1cfaba8c-1523-11d1-ad79-00c04fd8fdff}\ProxyStubClsid32
 *        -> {6f9b0f2a-6a6a-4bf1-9c0d-3aa1b4f0c001}
 *   HKCR\Interface\{31739d04-3471-4cf4-9a7c-57a44ae71956}\ProxyStubClsid32
 *        -> same
 *   HKCR\CLSID\{6f9b0f2a-...}\InprocServer32
 *        -> C:\windows\system32\wine-shims\wmi-unsecapp-ps.dll
 *
 * which is how the standard marshaler finds an IPSFactoryBuffer for those
 * IIDs.  Without this, creating the object out-of-process works but querying
 * it for IUnsecuredApartment fails with E_NOINTERFACE.
 */

#include <windows.h>
#include <initguid.h>

/* Both of these must be defined BEFORE <rpcproxy.h> is included:
 *
 *   REGISTER_PROXY_DLL  gates the DllRegisterServer/DllUnregisterServer
 *                       declarations, so `regsvr32 wmi-unsecapp-ps.dll` can
 *                       register the ProxyStubClsid32 keys by itself.
 *   PROXY_CLSID_IS      is what rpcproxy.h binds GET_DLL_CLSID to, and
 *                       GET_DLL_CLSID is what DllGetClassObject compares the
 *                       requested CLSID against.  Defining it later still
 *                       compiles, but GET_DLL_CLSID then falls back to
 *                       aProxyFileList[0]->pStubVtblList[0]->header.piid --
 *                       the IID of the first interface in the proxy file
 *                       list -- so the DLL silently answers to
 *                       {7c857801-7381-11cf-884d-00aa004b2e24} instead, and
 *                       CoGetClassObject on the registered proxy/stub CLSID fails
 *                       with CLASS_E_CLASSNOTAVAILABLE.
 */
#define REGISTER_PROXY_DLL
/* rpcproxy.h turns this into
 *     const CLSID CLSID_PSFactoryBuffer = { ... };
 * and points PROXY_CLSID at it.  (Writing DEFINE_GUID + PROXY_CLSID instead
 * conflicts: rpcproxy.h declares the name as a non-const `extern CLSID`,
 * while DEFINE_GUID defines it const.) */
#define PROXY_CLSID_IS {0x6f9b0f2a, 0x6a6a, 0x4bf1, {0x9c, 0x0d, 0x3a, 0xa1, 0xb4, 0xf0, 0xc0, 0x01}}

#include <rpcproxy.h>

/* Interface IIDs live in the widl-generated file. */
#include "wmi_unsecapp_ps_i.c"

/* generated: aProxyFileList + the entry points */
#include "dlldata.c"
